#!/usr/bin/env bun

const usage = `Usage: opencode-chat-room [options]

Options:
  -h, --help             Show this help
  -v, --version          Show the package version
  -H, --host <host>      Bind hostname
  -p, --port <port>      Bind port (1-65535)
  -t, --token <token>    Enable bearer token authentication

Commands:
  watch run|start|status|stop`;

type ValueOption = "host" | "port" | "token";
const values: Partial<Record<ValueOption, string>> = {};
let help = false;
let version = false;

function fail(message: string): never {
  console.error(`Error: ${message}\n\n${usage}`);
  process.exit(1);
}

function setValue(name: ValueOption, value: string | undefined): void {
  if (value === undefined || value === "") {
    fail(`Missing value for --${name}`);
  }
  values[name] = value;
}

function validatePort(value: string): void {
  const port = Number(value);
  if (!Number.isInteger(port) || port < 1 || port > 65535) {
    fail(`Invalid port "${value}": expected an integer from 1 to 65535`);
  }
}

const args = process.argv.slice(2);
if (args[0] === "watch") {
  const action = args[1];
  if ((args.length === 2 && (action === "help" || action === "--help")) ||
    (args.length === 3 && args[2] === "--help")) {
    console.log("Usage: opencode-chat-room watch run|start|status|stop");
    process.exit(0);
  }
  if (args.length !== 2 || !["run", "start", "status", "stop"].includes(action ?? "")) {
    fail("Expected watch run, start, status, or stop");
  }
  const watcher = await import("./src/runtime/watch.ts");
  try {
    if (action === "run") await watcher.runWatcher();
    else if (action === "start") console.log(await watcher.startWatcher());
    else if (action === "status") console.log(await watcher.watchStatus());
    else console.log(await watcher.stopWatcher());
  } catch (error) {
    console.error(`watch: ${error instanceof Error ? error.message : "operation failed"}`);
    process.exitCode = 1;
  }
  process.exit(process.exitCode ?? 0);
}
for (let i = 0; i < args.length; i += 1) {
  const arg = args[i]!;
  if (arg === "-h" || arg === "--help") {
    help = true;
    continue;
  }
  if (arg === "-v" || arg === "--version") {
    version = true;
    continue;
  }

  const equals = arg.match(/^--(host|port|token)=(.*)$/);
  if (equals) {
    const name = equals[1] as ValueOption;
    setValue(name, equals[2]);
    continue;
  }

  const name =
    arg === "-H" || arg === "--host"
      ? "host"
      : arg === "-p" || arg === "--port"
        ? "port"
        : arg === "-t" || arg === "--token"
          ? "token"
          : undefined;
  if (name) {
    const value = args[++i];
    if (value?.startsWith("-") && !(name === "port" && /^-\d+$/.test(value))) {
      fail(`Missing value for --${name}`);
    }
    setValue(name, value);
    continue;
  }
  fail(`Unknown option: ${arg}`);
}

if (help) {
  console.log(usage);
  process.exit(0);
}

if (version) {
  const packageJson = (await Bun.file(
    new URL("./package.json", import.meta.url),
  ).json()) as { version?: string };
  console.log(packageJson.version ?? "unknown");
  process.exit(0);
}

if (values.port !== undefined) {
  validatePort(values.port);
  process.env.CHAT_ROOM_SERVER_PORT = values.port;
}
if (values.host !== undefined) {
  process.env.CHAT_ROOM_SERVER_HOST = values.host;
}
if (values.token !== undefined) {
  process.env.CHAT_ROOM_SERVER_TOKEN = values.token;
}

const { default: server } = await import("./server/chat-server");
Bun.serve(server);

// ponytail: library surface — the room domain model; plugin wiring and
// file persistence stay internal
export { default } from "./plugin";
export { id, server, setup } from "./plugin";
export { default as RoomService, RoomError } from "./src/rooms/room-service.ts";
export type {
  Message,
  Participant,
  Room,
  RoomErrorCode,
} from "./src/rooms/room-service.ts";

import { tool } from "@opencode-ai/plugin";
import type { ToolContext as V1ToolContext } from "@opencode-ai/plugin";
import { AsyncLocalStorage } from "node:async_hooks";
import { z } from "zod";
import RoomService, { RoomError, type Message } from "./src/rooms/room-service.ts";
import {
  formatRoom,
  acknowledgeReadWithReceipts,
  identity,
  loadRegistry,
  loadRooms,
  writeState,
  readState,
  readUnreadMessages,
  recallMessage,
  senderName,
  timeOf,
  type Registry,
  type RegistryEntry,
} from "./src/state/store.ts";
import { flushReceiptCandidates, receiptDestination } from "./src/agent/agent-receipts.ts";
import { centerAction, deleteAgentResource } from "./src/center/center-client.ts";
import { createQueueTransport, type QueueTransport } from "./src/center/queue-transport.ts";
import { checkCenterInbox } from "./src/center/center-inbox.ts";
import { assertDeliveryLease } from "./src/center/session-delivery.ts";
import { wakeSessions } from "./src/center/center-wake.ts";
import { clearPendingAdmission } from "./src/center/queue.ts";
import { createNotifier } from "./src/runtime/plugin-notifications.ts";
import { explicitlyAddresses } from "./src/center/mentions.ts";
import { createV2Setup, type V2Runtime } from "./src/runtime/v2-plugin.ts";
import { createV1Server } from "./src/runtime/v1-plugin.ts";
import { runAnnouncementTool } from "./src/agent/announcement-tool.ts";
import { uploadAgentResource } from "./src/rooms/resource-upload.ts";
import { readAgentResource, resourceReadFailure } from "./src/rooms/resource-read.ts";
import { adminTool, adminToolDescription, adminToolSchema } from "./src/agent/admin-client.ts";
import { runReminderTool } from "./src/center/reminder-client.ts";
// ponytail: CHAT_ROOM_SERVER_URL switches to central mode (all state on a
// central server); unset = standalone local-file mode
const centerUrl = process.env.CHAT_ROOM_SERVER_URL ?? "";
const centerToken = process.env.CHAT_ROOM_SERVER_TOKEN ?? "";
// A configured OpenCode serve URL is required to wake exited sessions.
const serveWakeUrl = process.env.CHAT_ROOM_WAKE_SERVE_URL ?? "";
type PluginRuntime = V2Runtime;

const runtimeContext = new AsyncLocalStorage<PluginRuntime>();
const defaultRuntime: PluginRuntime = {
  selfServerUrl: "",
  selfDirectory: "",
  protocol: "v1",
  transport: createQueueTransport(),
  center: { center: centerUrl, token: centerToken, directory: "" },
};
const currentRuntime = (): PluginRuntime => runtimeContext.getStore() ?? defaultRuntime;

async function withRooms<T>(
  fn: (svc: RoomService, registry: Registry) => T,
  readOnly = false,
): Promise<T> {
  const run = (svc: RoomService, registry: Registry): T => {
    try {
      return fn(svc, registry);
    } catch (err) {
      if (err instanceof RoomError) {
        return `error: ${err.message}` as unknown as T;
      }
      throw err;
    }
  };
  return readOnly ? readState(run) : writeState(run);
}

function registerSelfInState(
  service: RoomService,
  reg: Registry,
  runtime: PluginRuntime,
  roomId: string,
  sessionID: string,
  name = identity(),
  receiverOwnerID?: string,
): void {
      const latestMessageTs = service.listRooms().find((room) => room.id === roomId)?.messages.at(-1)?.createdAt ?? 0;
      const regRoom = (reg[roomId] =
        reg[roomId] ?? Object.create(null) as Record<string, RegistryEntry>);
      regRoom[sessionID] = {
        serverUrl: runtime.selfServerUrl,
        apiPrefix: runtime.protocol === "v1" ? "" : "/api",
        protocol: runtime.protocol,
        ...(receiverOwnerID ? { receiverOwnerID } : regRoom[sessionID]?.receiverOwnerID ? { receiverOwnerID: regRoom[sessionID]!.receiverOwnerID } : {}),
        name,
        directory: runtime.selfDirectory || undefined,
        // ponytail: re-join must not rewind the read watermark (unread
        // messages before the re-join would be silently dropped); a first
        // join starts reading at join time
        lastReadTs:
          regRoom[sessionID]?.lastReadTs ??
          Math.max(Date.now(), latestMessageTs),
        lastQueuedTs: regRoom[sessionID]?.lastQueuedTs,
      };
}

function unregisterSelfInState(reg: Registry, roomId: string, sessionID: string): void {
  if (!reg[roomId]) return;
  delete reg[roomId][sessionID];
  if (!Object.keys(reg[roomId]).length) delete reg[roomId];
}

async function refreshSelf(runtime: PluginRuntime, sessionID: string): Promise<void> {
  await writeState((_svc, registry) => {
    try {
      for (const members of Object.values(registry)) {
        const entry = members[sessionID];
        if (!entry) continue;
        if (runtime.protocol === "v2" && (entry.directory !== runtime.selfDirectory ||
          entry.receiverOwnerID && entry.receiverOwnerID !== runtime.transport.receiverOwnerID)) continue;
        entry.serverUrl = runtime.selfServerUrl;
        entry.apiPrefix = runtime.protocol === "v1" ? "" : "/api";
        entry.protocol = runtime.protocol;
        if (runtime.protocol !== "v2") entry.directory = runtime.selfDirectory || undefined;
      }
    } catch {
      // Existing watermarks and identities remain untouched if refresh fails.
    }
  });
}

// ponytail: push is best-effort; poll remains the fallback; log every attempt for debugging
async function bumpLastRead(
  roomId: string,
  sessionID: string,
  ts: number,
): Promise<boolean> {
  assertDeliveryLease();
  const updated = await writeState((_svc, reg) => {
    try {
      const entry = reg[roomId]?.[sessionID];
      if (entry) {
        // never rewind: an older in-flight push must not lower the watermark
        entry.lastReadTs = Math.max(entry.lastReadTs ?? 0, ts);
        return true;
      }
      return false;
    } catch {
      // best-effort: an unpromoted read position only means poll repeats
      return false;
    }
  });
  if (updated) clearPendingAdmission(sessionID, roomId, ts);
  return updated;
}

export async function acknowledgeStandalonePoll(roomID: string, sessionID: string, throughTs: number,
  messages: Message[], identityForReceipt?: { membershipID: string; receiverOwnerID?: string }): Promise<void> {
  if (!identityForReceipt) { await bumpLastRead(roomID, sessionID, throughTs); return; }
  if (!messages.length || !messages.every((message) => typeof message.id === "string" && message.id)) return;
  const result = await acknowledgeReadWithReceipts(roomID, sessionID, throughTs, messages.map((message) => message.id!), "tool", identityForReceipt);
  if (result.status === "ok") clearPendingAdmission(sessionID, roomID, result.readThroughTs ?? 0);
}

async function bumpLastQueued(
  roomId: string,
  sessionID: string,
  ts: number,
): Promise<boolean> {
  assertDeliveryLease();
  const updated = await writeState((_svc, reg) => {
    try {
      const entry = reg[roomId]?.[sessionID];
      if (entry) {
        entry.lastQueuedTs = Math.max(entry.lastQueuedTs ?? 0, ts);
        return true;
      }
      return false;
    } catch {
      return false;
    }
  });
  if (updated) clearPendingAdmission(sessionID, roomId, ts);
  return updated;
}

const notifier = createNotifier({
  transport: () => currentRuntime().transport,
  bumpQueued: (roomId, sessionID, ts) => bumpLastQueued(roomId, sessionID, ts),
});
const { notifyRoom, notifyTarget } = notifier;
const restoreScans = new Map<string, { afterTs: number; untilTs?: number }>();
const restoreKey = (sid: string, roomID: string, ownerID = "") => JSON.stringify([ownerID, sid, roomID]);
export async function pollKnownSessions(
  sessions: ReadonlySet<string>,
  transport: QueueTransport,
  opts: PluginRuntime["center"],
): Promise<void> {
  if (opts.center) {
    await Promise.all([...sessions].map((sessionID) =>
      checkCenterInbox(opts, sessionID, transport),
    ));
    if (transport.receiverOwnerID) await flushReceiptCandidates({ destination: receiptDestination(opts.center), receiverOwnerID: transport.receiverOwnerID, center: opts.center, token: opts.token }).catch(() => {});
    return;
  }
  const [rooms, registry] = await Promise.all([loadRooms(), loadRegistry()]);
  for (const sessionID of sessions) {
    const mentionOnly = transport.mentionOnlySessions?.has(sessionID) ?? false;
    for (const room of rooms) {
      const entry = registry[room.id]?.[sessionID];
      if (!entry) continue;
      if (transport.protocol === "v2" && entry.receiverOwnerID &&
        (entry.protocol !== "v2" || entry.receiverOwnerID !== transport.receiverOwnerID)) continue;
      if (mentionOnly && (entry.protocol !== "v2" || entry.receiverOwnerID !== transport.receiverOwnerID)) continue;
      const cursor = Math.max(entry.lastReadTs ?? 0, entry.lastQueuedTs ?? 0);
      const key = restoreKey(sessionID, room.id, transport.receiverOwnerID);
      let scan = restoreScans.get(key) ?? { afterTs: cursor };
      if (scan.afterTs < cursor) scan = { ...scan, afterTs: cursor };
      if (mentionOnly && (scan.untilTs === undefined || scan.untilTs <= cursor)) {
        scan.untilTs = undefined;
        const tail = await readUnreadMessages(room.id, cursor, 20, sessionID, entry.name, true);
        if (tail.items.some((message) => explicitlyAddresses(message, entry.name, sessionID, room.kind))) {
          scan.untilTs = tail.items.at(-1)!.createdAt;
          scan.afterTs = Math.max(scan.afterTs, scan.untilTs);
        } else {
          const candidates = await readUnreadMessages(room.id, scan.afterTs, 20, sessionID, entry.name);
          if (!candidates.items.length) { restoreScans.set(key, scan); continue; }
          scan.afterTs = candidates.items.at(-1)!.createdAt;
          if (candidates.items.some((message) => explicitlyAddresses(message, entry.name, sessionID, room.kind))) scan.untilTs = scan.afterTs;
          restoreScans.set(key, scan);
          if (scan.untilTs === undefined) continue;
        }
      }
      if (mentionOnly) restoreScans.set(key, scan);
      const page = await readUnreadMessages(room.id, cursor, 20, sessionID, entry.name);
      if (!page.items.length) continue;
      const target = mentionOnly ? { ...transport, mentionOnlySessions: new Set([...transport.mentionOnlySessions!].filter((id) => id !== sessionID)) } : transport;
      await notifyTarget(sessionID, {
        roomId: room.id,
          roomName: room.name,
          roomKind: room.kind ?? "group",
          messages: page.items,
      }, target);
      if (mentionOnly && scan.untilTs !== undefined) {
        const queued = (await loadRegistry())[room.id]?.[sessionID]?.lastQueuedTs ?? cursor;
        if (queued >= scan.untilTs) restoreScans.delete(key);
      }
    }
  }
  await flushReceiptCandidates({ destination: receiptDestination(""), receiverOwnerID: transport.receiverOwnerID }).catch(() => {});
}

const READ_ONLY_ACTIONS = new Set(["list", "members", "poll", "join_status", "announcement_list", "announcement_read"]);

export const roomArgs = z.object({
  action: z.enum(["create", "join", "join_status", "leave", "list", "send", "poll", "recall", "members", "upload_resource", "read_resource", "delete_resource", "announcement_list", "announcement_read", "announcement_write", "announcement_delete", "reminder_list", "reminder_create", "reminder_update", "reminder_delete"]),
  name: z.string().max(64).optional().describe("For join: your own participant display name, NOT the room name (required). For create: the new room name."),
  roomId: z.string().optional(),
  messageId: z.string().optional().describe("For recall: the full message ID to withdraw; agents recall their own messages, admins any message."),
  resourceId: z.string().optional(),
  filePath: z.string().optional().describe("Local regular file to upload; central mode only; requires host read permission."),
  text: z.string().max(5000).optional(),
  isQuestion: z.boolean().optional(),
  announcementName: z.string().optional().describe("Name of a room announcement; distinct from participant or room name."),
  content: z.string().optional().describe("Announcement content, at most 5000 Unicode characters."),
  reminderId: z.string().optional(),
  schedule: z.discriminatedUnion("type", [z.object({ type: z.literal("once"), at: z.string(), timezone: z.string().refine((value) => { try { new Intl.DateTimeFormat("en", { timeZone: value }); return true; } catch { return false; } }, "timezone must be an IANA timezone").optional() }), z.object({ type: z.literal("cron"), expression: z.string().regex(/^\S+\s+\S+\s+\S+\s+\S+\s+\S+$/), timezone: z.string().refine((value) => { try { new Intl.DateTimeFormat("en", { timeZone: value }); return true; } catch { return false; } }, "timezone must be an IANA timezone").optional() })]).optional(),
  paused: z.boolean().optional(),
  joinPolicy: z.enum(["open", "approval"]).optional().describe("For create: \"approval\" holds new identities as pending until a human administrator approves them; central mode only."),
}).superRefine((args, ctx) => {
  if (args.action === "join" && !args.name?.trim()) {
    ctx.addIssue({ code: "custom", path: ["name"], message: "name is required to join a room" });
  }
});
type RoomArguments = z.infer<typeof roomArgs>;

const roomExecute = async (
  args: RoomArguments,
  context: V1ToolContext & { signal?: AbortSignal },
) => {
    if (args.action === "join" && !args.name?.trim()) return "error: name is required to join a room";
    const runtime = currentRuntime();
    if (args.action === "reminder_list" || args.action === "reminder_create" || args.action === "reminder_update" || args.action === "reminder_delete") {
      return await runReminderTool(runtime.center, args, context.sessionID);
    }
    if (args.action === "upload_resource") return uploadAgentResource(runtime.center, args.roomId ?? "", args.filePath ?? "", context.sessionID, context);
    if (args.action === "delete_resource") return deleteAgentResource(runtime.center, args.roomId ?? "", args.resourceId ?? "", context.sessionID);
    if (args.action === "read_resource") {
      try {
        if (!context.ask) return "error: host webfetch permission is unavailable";
        return await readAgentResource(runtime.center, args.roomId ?? "", args.resourceId ?? "", context, context.abort ?? context.signal);
      } catch (error) { return `error: ${resourceReadFailure(error)}`; }
    }
    try {
      const explicitV2Join = runtime.protocol === "v2" && (args.action === "create" || args.action === "join");
      const receiverOwnerID = explicitV2Join && runtime.transport.verifySession
        ? await runtime.transport.verifySession(context.sessionID) : undefined;
      if (runtime.center.center) {
        // ponytail: central mode — self-pull inbox first, then act via HTTP
        // (skipped for poll: poll itself pulls the inbox, so racing the
        // fire-and-forget check would read the position it just advanced)
        if (args.action !== "poll") {
          void checkCenterInbox(runtime.center, context.sessionID, runtime.transport);
        }
        return await centerAction(runtime.center, {
          ...args,
          ...(runtime.protocol === "v2" ? { protocol: "v2" as const, receiverOwnerID } : {}),
        }, context.sessionID);
      }
      if (args.action === "recall") {
        if (!args.roomId) return "error: roomId is required";
        if (!args.messageId) return "error: messageId is required";
        try {
          const recalled = await recallMessage(args.roomId, args.messageId, context.sessionID);
          switch (recalled.status) {
            case "ok": return `recalled message ${recalled.messageID}`;
            case "missing": return `error: message not found: ${args.messageId}`;
            case "member": return "error: not joined";
            case "forbidden": return "error: only the sender or a room admin can recall this message";
          }
        } catch (err) {
          return `error: ${err instanceof Error ? err.message : String(err)}`;
        }
      }
      const announcementResult = await runAnnouncementTool(args, context.sessionID);
      if (announcementResult !== undefined) return announcementResult;
      // ponytail: act as the identity this session registered with on join
      let selfName = identity();
      let joinPrevName: string | undefined;
      let joinPrevShared = false;
      let leaveNameShared = false;
      let pollLastRead = 0;
      let pollEntry = false;
      let pollIdentity: { membershipID: string; receiverOwnerID?: string } | undefined;
      let pollPage: Awaited<ReturnType<typeof readUnreadMessages>> | undefined;
      let pollMaxTs: number | undefined;
      const notifications: Array<{ roomId: string; roomName: string; messages: Message[] }> = [];
      if (args.action === "poll" && args.roomId) {
        const entry = (await loadRegistry())[args.roomId]?.[context.sessionID];
        pollEntry = entry !== undefined;
        if (entry?.membershipID) pollIdentity = { membershipID: entry.membershipID, ...(entry.receiverOwnerID ? { receiverOwnerID: entry.receiverOwnerID } : {}) };
        selfName = entry?.name ?? selfName;
        pollLastRead = entry?.lastReadTs ?? 0;
        if (entry) pollPage = await readUnreadMessages(args.roomId, pollLastRead, 100, context.sessionID, selfName);
      }
      const result = await withRooms<string>(
        (svc, registry) => {
        notifications.length = 0;
        if (args.roomId) {
          const members = registry[args.roomId] ?? {};
          if (args.action === "send" || args.action === "leave" || args.action === "poll") selfName = members[context.sessionID]?.name ?? selfName;
          if (args.action === "join") joinPrevName = members[context.sessionID]?.name;
          if (args.action === "join" && joinPrevName) joinPrevShared = Object.entries(members).some(([sid, entry]) => sid !== context.sessionID && entry.name === joinPrevName);
          if (args.action === "leave") leaveNameShared = Object.entries(members).some(([sid, entry]) => sid !== context.sessionID && entry.name === selfName);
          if (args.action === "poll") pollEntry = members[context.sessionID] !== undefined;
        }
        switch (args.action) {
          case "create": {
            if (!args.name?.trim()) {
              return "error: name is required";
            }
            if (args.joinPolicy === "approval") {
              return "error: joinPolicy \"approval\" requires central mode (set CHAT_ROOM_SERVER_URL); local rooms are always open";
            }
            const created = svc.createRoom(args.name.trim(), identity());
            registerSelfInState(svc, registry, runtime, created.id, context.sessionID, undefined, receiverOwnerID);
            return formatRoom(svc, created);
          }
          case "join": {
            if (!args.roomId) {
              return "error: roomId is required";
            }
            const me = identity(args.name!.trim());
            // ponytail: F5 — re-join under a new name retires the old
            // participant, otherwise every rename leaks a ghost member;
            // skipped when another session still holds the old name
            if (
              joinPrevName !== undefined &&
              joinPrevName !== me &&
              !joinPrevShared &&
              svc.containsParticipant(args.roomId, joinPrevName)
            ) {
              svc.leaveRoom(args.roomId, joinPrevName);
            }
            const already = svc.containsParticipant(args.roomId, me);
            svc.joinRoom(args.roomId, { id: me, name: me });
            const room = svc.getRoom(args.roomId);
            registerSelfInState(svc, registry, runtime, args.roomId, context.sessionID, me, receiverOwnerID);
            if (!already) {
              // ponytail: membership events live in the message stream, so
              // the join notification rides the normal unread push
              svc.addEvent(args.roomId, `${me} joined the room`);
              notifications.push({ roomId: args.roomId, roomName: room.name, messages: [...room.messages] });
            }
            return formatRoom(svc, room);
          }
          case "leave": {
            if (!args.roomId) {
              return "error: roomId is required";
            }
            // ponytail: ora-2 M2 — mirror the join guard: if another session
            // still holds this name, remove only the registry entry, not the
            // participant (or the sibling window breaks with NOT_JOINED);
            // Do not emit a false leave event while the participant remains.
            if (!leaveNameShared) {
              svc.leaveRoom(args.roomId, selfName);
              const room = svc.getRoom(args.roomId);
              svc.addEvent(args.roomId, `${selfName} left the room`);
              notifications.push({ roomId: args.roomId, roomName: room.name, messages: [...room.messages] });
            }
            unregisterSelfInState(registry, args.roomId, context.sessionID);
            return `left room ${args.roomId}`;
          }
          case "list": {
            const rooms = svc.listRooms();
            if (rooms.length === 0) {
              return "no rooms yet";
            }
            return rooms
              .map(
                (r) =>
                  `${r.id} (${r.name}): ${svc.getParticipants(r.id).length} members`,
              )
              .join("\n");
          }
          case "members": {
            if (!args.roomId) {
              return "error: roomId is required";
            }
            const members = svc.getParticipants(args.roomId);
            return members.length > 0
              ? members.map((m) => m.name).join("\n")
              : "no members";
          }
          case "join_status": {
            if (!args.roomId) {
              return "error: roomId is required";
            }
            return registry[args.roomId]?.[context.sessionID]
              ? `joined room ${args.roomId}`
              : `none: not registered in room ${args.roomId}; run join with your name (local rooms are always open)`;
          }
          case "send": {
            if (!args.roomId) {
              return "error: roomId is required";
            }
            if (!args.text?.trim()) {
              return "error: text is required";
            }
            const msg = svc.sendMessage(
              args.roomId,
              selfName,
              args.text,
              context.sessionID,
              args.isQuestion,
            );
            const room = svc.getRoom(args.roomId);
            notifications.push({ roomId: args.roomId, roomName: room.name, messages: [...room.messages] });
            return `sent: ${args.text}\nmessage id: ${msg.id}\n${formatRoom(svc, room)}`;
          }
          case "poll": {
            if (!args.roomId) {
              return "error: roomId is required";
            }
            // ponytail: gate on registry entry (session granularity) — a
            // participant-id check would pass for any session sharing the
            // same host identity
            if (!pollEntry) {
              return "error: not joined";
            }
            if (!svc.containsParticipant(args.roomId, selfName)) {
              return "error: not joined";
            }
            // ponytail: only messages newer than this session's last read (or
            // last successful push) — queue-notified messages don't repeat
            const messages = (pollPage?.items ?? []).filter((message) => !message.recalledAt);
            if (messages.length === 0) {
              return "no new messages";
            }
            pollMaxTs = messages.reduce(
              (mx, m) => Math.max(mx, m.createdAt),
              0,
            );
            return messages
              .map(
                (m) =>
                  `[${timeOf(m.createdAt)}] ${senderName(svc, m)}: ${m.text} (id: ${m.id})`,
              )
              .join("\n") + (pollPage?.hasMore ? "\nMore unread messages remain; poll again." : "");
          }
          default:
            return "error: unsupported room action";
        }
      }, READ_ONLY_ACTIONS.has(args.action));
      for (const notification of notifications) {
        void notifyRoom(notification.roomId, notification.roomName,
          context.sessionID, notification.messages).catch(() => {});
      }
      if (args.action === "poll" && pollMaxTs !== undefined && pollMaxTs > 0) {
        await acknowledgeStandalonePoll(args.roomId!, context.sessionID, pollMaxTs,
          (pollPage?.items ?? []).filter((message) => !message.recalledAt), pollIdentity);
      }
      return result;
    } catch (err) {
      return `error: ${err instanceof Error ? err.message : String(err)}`;
    }
};
